import { ErrorHandlingService } from './ErrorHandlingService';

// Error types for consistent categorization
export const ErrorTypes = {
  NETWORK: 'network',
  AUTHENTICATION: 'auth',
  PERMISSION: 'permission',
  VALIDATION: 'validation',
  GEOLOCATION: 'geolocation',
  STORAGE: 'storage',
  UNKNOWN: 'unknown'
};

// Standard user-friendly messages by type
const USER_MESSAGES = {
  [ErrorTypes.NETWORK]: 'Network connection issue. Please check your connection and try again.',
  [ErrorTypes.AUTHENTICATION]: 'Please log in to continue.',
  [ErrorTypes.PERMISSION]: 'You don\'t have permission to perform this action.',
  [ErrorTypes.VALIDATION]: 'Please check your input and try again.',
  [ErrorTypes.GEOLOCATION]: 'Unable to access your location. Please check your location settings.',
  [ErrorTypes.STORAGE]: 'Unable to upload or access files. Please try again later.',
  [ErrorTypes.UNKNOWN]: 'An unexpected error occurred. Please try again later.'
};

/**
 * Handle an error with consistent formatting and recovery
 * @param {Error} error - The error to handle
 * @param {string} type - Error type from ErrorTypes
 * @param {Object} context - Additional context for error handling
 * @returns {Promise<Object>} - Error handling result
 */
export const handleError = async (error, type = ErrorTypes.UNKNOWN, context = {}) => {
  // Log the error with context
  console.error(`[${type.toUpperCase()}]`, error, context);
  
  // Create standardized error object
  const errorObject = {
    message: USER_MESSAGES[type] || USER_MESSAGES[ErrorTypes.UNKNOWN],
    originalError: error,
    type,
    context,
    timestamp: Date.now()
  };
  
  // Handle error with recovery attempt
  try {
    const recovered = await ErrorHandlingService.handleError(error, type, context);
    return {
      ...errorObject,
      recovered,
      recoveryTimestamp: Date.now()
    };
  } catch (recoveryError) {
    console.error(`Recovery attempt failed for ${type}:`, recoveryError);
    return {
      ...errorObject,
      recovered: false,
      recoveryError
    };
  }
};

/**
 * Create a validation error
 * @param {string} message - Validation error message
 * @param {Object} context - Additional context
 * @returns {Error} - Validation error
 */
export const createValidationError = (message, context = {}) => {
  const error = new Error(message);
  error.type = ErrorTypes.VALIDATION;
  error.context = context;
  return error;
};

